import{Lt as e,Vt as t,Z as n,_t as r,bt as i,mt as a,vt as o,yt as s}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var c=JSON.parse(`{"title":"校外访问抓取的问题","description":"","frontmatter":{"title":"校外访问抓取的问题","date":"2025-04-10T00:00:00.000Z"},"headers":[],"relativePath":"user-guide/faqs/off-campus-access.md","filePath":"wiki/user-guide/faqs/off-campus-access.md"}`),l={name:`user-guide/faqs/off-campus-access.md`},u={class:`table-of-contents`},d={href:`#更新-zotero-的转换器`},f={href:`#使用数据库官方提供的外部访问服务`},p={href:`#使用学校的-vpn`},m={href:`#使用学校的-webvpn`},h={href:`#使用其它方式添加条目`},g={id:`更新-zotero-的转换器`,tabindex:`-1`},_={id:`使用数据库官方提供的外部访问服务`,tabindex:`-1`},v={id:`使用学校的-vpn`,tabindex:`-1`},y={id:`使用学校的-webvpn`,tabindex:`-1`},b={id:`使用其它方式添加条目`,tabindex:`-1`};function x(n,c,l,x,S,C){let w=t(`Badge`),T=t(`NolebaseGitContributors`),E=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[c[22]||=a(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidefaqsoff-campus-access.md for this page in Markdown format`,-1),c[23]||=a(`h1`,{id:`校外访问的常见问题`,tabindex:`-1`},[s(`校外访问的常见问题 `),a(`a`,{class:`header-anchor`,href:`#校外访问的常见问题`,"aria-label":`Permalink to “校外访问的常见问题”`},`​`)],-1),c[24]||=a(`p`,null,`本文整理了一些关于校外访问文献资源的常见问题及解决方法。你可以在右侧大纲栏（部分窄屏设备也可能在顶部「页面导航」）或下面的目录快速定位到你需要的内容。`,-1),a(`nav`,u,[a(`ul`,null,[c[6]||=a(`li`,null,[a(`a`,{href:`#校外访问的基本概念`},`校外访问的基本概念`)],-1),a(`li`,null,[c[4]||=a(`a`,{href:`#解决校外访问抓取失败的问题`},`解决校外访问抓取失败的问题`,-1),a(`ul`,null,[a(`li`,null,[a(`a`,d,[c[0]||=s(`更新 Zotero 的转换器`,-1),i(w,{text:`初级`})])]),a(`li`,null,[a(`a`,f,[c[1]||=s(`使用数据库官方提供的外部访问服务`,-1),i(w,{text:`初级`})])]),a(`li`,null,[a(`a`,p,[c[2]||=s(`使用学校的 VPN`,-1),i(w,{text:`中级`})])]),a(`li`,null,[a(`a`,m,[c[3]||=s(`使用学校的 WebVPN`,-1),i(w,{text:`高级`})])])])]),a(`li`,null,[a(`a`,h,[c[5]||=s(`使用其它方式添加条目`,-1),i(w,{text:`初级`})])])])]),c[25]||=o(`<h2 id="校外访问的基本概念" tabindex="-1">校外访问的基本概念 <a class="header-anchor" href="#校外访问的基本概念" aria-label="Permalink to “校外访问的基本概念”">​</a></h2><p>校外访问是指在不连接校园网的情况下，通过特定工具或服务访问学校购买的文献资源。常见的校外访问方式包括：</p><ul><li><strong>数据库官方提供的外部访问</strong>：一些数据库提供的校外访问服务（如中国知网的高校/机构外部访问系统、ScienceDirect 的通过您的组织访问）。该方法通常不限制网络环境，需要学校统一认证登录的账号密码进行身份认证。</li><li><strong>校外访问系统</strong>：学校提供的 VPN 或 WebVPN 服务。 <ul><li>VPN：通过客户端加密连接虚拟接入校内网络，全局代理所有流量，可访问所有内网资源（如数据库、教务系统），需下载客户端。</li><li>WebVPN：通过浏览器访问特定网页链接，仅代理浏览器内的网页请求，无需客户端但功能受限（仅支持部分资源且无法代理其他软件）。</li></ul></li><li><strong>学校镜像站</strong>：部分学校提供的文献数据库镜像站。</li></ul><p>此外，还有一些其他的资源获取方式：</p><ul><li><strong>社会图书馆镜像站</strong>：部分社会图书馆提供的文献数据库镜像站，如浙江图书馆、国家图书馆等单位提供的镜像站。</li><li><strong>第三方文献资源站</strong>：如 Unpaywall、Sci-Hub 等站点，提供免费获取文献的服务。</li><li><strong>文献互助平台</strong>：如科研通等平台，用户可以在上面分享和请求文献。</li></ul><details class="details custom-block"><summary>使用校外访问服务时抓取失败的常见原因</summary><p>通过校外访问服务访问数据库可能会导致 Zotero 无法正常抓取文献信息或附件，主要原因包括：</p><ul><li><strong>网址变更</strong>：部分校外访问工具和镜像站会修改原始网址，导致 Zotero 无法识别网址，从而无法调用正确的转换器进行抓取。</li><li><strong>页面内容变更</strong>：部分校外访问工具和镜像站会修改原始页面内容，导致针对源站开发的转换器无法适用于该站。</li><li><strong>缺少相应的转换器</strong>：部分第三方文献资源站和文献互助平台可能没有专为其开发的转换器，导致 Zotero 无法从页面上抓取条目信息或附件。</li><li><strong>兼容性问题</strong>：某些校外访问工具访问数据库时可能因兼容问题无法下载文献，具体表现为无限加载或无限人机验证。</li><li><strong>风控限制</strong>：大量抓取可能触发目标网站的风控机制，导致抓取失败，具体表现为人机验证。</li><li><strong>网络问题</strong>：网络不稳定或访问速度慢可能导致网站访问和抓取失败，具体表现为超时或连接错误。</li></ul><p>此外，学校的镜像站以及社会图书馆的镜像站可能与数据库官方的页面内容不一致，导致为源站开发的转换器可能无法完美兼容这些镜像站。而第三方的文献资源站和文献互助平台可能没有专为其开发的转换器，导致 Zotero 无法从页面上抓取条目信息或附件。</p></details><h2 id="解决校外访问抓取失败的问题" tabindex="-1">解决校外访问抓取失败的问题 <a class="header-anchor" href="#解决校外访问抓取失败的问题" aria-label="Permalink to “解决校外访问抓取失败的问题”">​</a></h2>`,7),a(`h3`,g,[c[7]||=s(`更新 Zotero 的转换器`,-1),i(w,{text:`初级`}),c[8]||=s(),c[9]||=a(`a`,{class:`header-anchor`,href:`#更新-zotero-的转换器`,"aria-label":`Permalink to “更新 Zotero 的转换器”`},`​`,-1)]),c[26]||=a(`p`,null,[s(`确保 Zotero 的转换器为最新版本。详细操作请参考：`),a(`a`,{href:`./update-translators`},`更新抓取文献信息的转换器`),s(`。`)],-1),c[27]||=a(`div`,{class:`tip custom-block`},[a(`p`,{class:`custom-block-title`},`提醒`),a(`p`,null,`无论您是否通过校外访问抓取文献条目，都建议定期更新 Zotero 的转换器，确保转换器能够适配数据库网站的最新变动。`)],-1),a(`h3`,_,[c[10]||=s(`使用数据库官方提供的外部访问服务`,-1),i(w,{text:`初级`}),c[11]||=s(),c[12]||=a(`a`,{class:`header-anchor`,href:`#使用数据库官方提供的外部访问服务`,"aria-label":`Permalink to “使用数据库官方提供的外部访问服务”`},`​`,-1)]),c[28]||=o(`<p>数据库官方提供的外部访问服务通常是最稳定的校外访问方式。该方法不会修改页面网址，无需转换器做特殊兼容，无需做特殊设置，且可在国外网络环境下使用。一般情况下，只要数据库官方支持通过你的学校/机构进行外部访问，就建议优先使用这一方式。</p><p>各个数据库的校外访问入口通常在数据库的登录页面中，也可能在文献的详情信息也上（通常会叫做 <code>Log in via an institution</code>、<code>Institution Login</code>、<code>Institutional Sign In</code> 等等）。以下整理了一些常见学术数据库的校外访问入口，供参考使用：</p><details class="details custom-block"><summary>常见学术数据库的校外访问入口</summary><h4 id="中文数据库" tabindex="-1">中文数据库 <a class="header-anchor" href="#中文数据库" aria-label="Permalink to “中文数据库”">​</a></h4><ul><li><strong>中国知网</strong><br> 使用 <a href="http://fsso.cnki.net" target="_blank" rel="noreferrer">中国知网高校/机构外部访问系统</a>。</li><li><strong>万方数据</strong><br> 使用 <a href="http://fsso.wanfangdata.com.cn" target="_blank" rel="noreferrer">万方数据机构外部访问系统</a>。</li><li><strong>维普期刊</strong><br> 访问 <a href="https://qikan.cqvip.com/" target="_blank" rel="noreferrer">维普期刊官网</a>，然后点击页面右上角的「登录」按钮，根据实际情况选择「第三方登录」中的「CARSI 馆外登录」或「中国科技云登录」。</li></ul><h4 id="英文综合数据库" tabindex="-1">英文综合数据库 <a class="header-anchor" href="#英文综合数据库" aria-label="Permalink to “英文综合数据库”">​</a></h4><ul><li><strong>Elsevier（ScienceDirect）</strong><br> 使用 <a href="https://www.sciencedirect.com/user/institution/login" target="_blank" rel="noreferrer">ScienceDirect 通过您的组织访问</a>。</li><li><strong>IEEE Xplore</strong><br> 访问 <a href="https://ieeexplore.ieee.org" target="_blank" rel="noreferrer">IEEE Xplore 官网</a>，然后点击页面上的「Institutional Sign In」。</li><li><strong>ProQuest</strong><br> 访问 <a href="https://search.proquest.com" target="_blank" rel="noreferrer">ProQuest 官网</a>，然后点击页面上的「通过您的图书馆登录以访问更多功能」。</li><li><strong>PubMed</strong><br> 无需使用校外访问，直接访问 <a href="https://pubmed.ncbi.nlm.nih.gov" target="_blank" rel="noreferrer">美国国立生物技术信息中心官网</a>。注意，PubMed 只是检索网站，不直接提供 PDF 附件下载。下载附件时可能仍然需要登录文献所在的数据库。</li><li><strong>SpringerLink</strong><br> 使用 <a href="https://wayf.springernature.com/?redirect_uri=https%3A%2F%2Flink.springer.com" target="_blank" rel="noreferrer">Springer 机构访问</a>。</li><li><strong>Taylor &amp; Francis</strong><br> 使用 <a href="https://www.tandfonline.com/action/ssostart?redirectUri=%2F" target="_blank" rel="noreferrer">Taylor &amp; Francis Shibboleth sign in</a>。</li><li><strong>Web of Science</strong><br> 无需使用校外访问，直接访问 <a href="https://webofscience.clarivate.cn/" target="_blank" rel="noreferrer">Web of Science 官网</a>。注意，Web of Science 只是检索网站，不直接提供 PDF 附件下载。下载附件时可能仍然需要登录文献所在的数据库。</li><li><strong>Wiley Online Library</strong><br> 使用 <a href="https://onlinelibrary.wiley.com/action/ssostart?redirectUri=%2F" target="_blank" rel="noreferrer">Wiley 机构登录</a>。</li></ul></details>`,3),a(`h3`,v,[c[13]||=s(`使用学校的 VPN`,-1),i(w,{text:`中级`}),c[14]||=s(),c[15]||=a(`a`,{class:`header-anchor`,href:`#使用学校的-vpn`,"aria-label":`Permalink to “使用学校的 VPN”`},`​`,-1)]),c[29]||=a(`p`,null,`通过学校的 VPN 客户端连接校园网是较为的校外访问方式。该方法可以全局代理所有流量，以校园网环境访问所有内网资源（如数据库、教务系统），需要下载客户端，但不需要额外的配置。`,-1),a(`h3`,y,[c[16]||=s(`使用学校的 WebVPN`,-1),i(w,{text:`高级`}),c[17]||=s(),c[18]||=a(`a`,{class:`header-anchor`,href:`#使用学校的-webvpn`,"aria-label":`Permalink to “使用学校的 WebVPN”`},`​`,-1)]),c[30]||=o(`<p>如果通过学校的 WebVPN 访问数据库，实际访问的链接会变得与数据库官网的原始链接不同，很有可能导致 Zotero Connector 无法为该网站正确匹配到相应的转换器，最终只能抓到一个网页快照。</p><p>如果您需要使用学校的 WebVPN 访问数据库，请阅读下面的教程配置 Zotero Connector 选项中的「Proxies」。</p><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>Zotero Connector 的「Proxies」选项配置较为繁琐，建议优先使用其他校外方式途径访问数据库。</p><p>如果您仍需使用 WebVPN 访问数据库，请仔细阅读下面的 Zotero Connector 代理配置教程，正确配置 Zotero Connector 的「Proxies」选项，确保 Zotero Connector 能够正确识别经 WebVPN 代理后的页面链接。</p></div><details class="details custom-block"><summary>Zotero Connector 代理配置教程</summary><div class="warning custom-block"><p class="custom-block-title">注意</p><p>Apple Safari 浏览器的 Zotero Connector 目前不支持配置代理规则。macOS 用户建议使用 Microsoft Edge、Google Chrome 或 Mozilla Firefox 浏览器抓取文献。</p></div><h4 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to “配置步骤”">​</a></h4><p>不同的 WebVPN 的链接结构可能不同，在配置 Zotero Connector 的代理规则时，需要根据实际的 WebVPN 代理链接的结构特点进行处理。这里以一篇万方官网的期刊文章为例进行说明。</p><p>假设原始链接为：<code>https://d.wanfangdata.com.cn/periodical/hjkxyj202501001</code></p><ol><li><p><strong>分析链接结构</strong></p><p>首先，需要分析原始链接的结构，确定协议、主机和路径部分。示例原始链接的结构如下：</p></li></ol><table tabindex="0"><thead><tr><th>结构项</th><th>内容</th></tr></thead><tbody><tr><td>Protocol（协议）</td><td><code>https://</code></td></tr><tr><td>Host（主机）</td><td><code>d.wanfangdata.com.cn</code></td></tr><tr><td>Path（路径）</td><td><code>periodical/hjkxyj202501001</code></td></tr></tbody></table><ol><li><p><strong>确定代理链接的结构特点</strong></p><p>WebVPN 代理通常有两种主要类型：</p><ul><li><strong>类型 1</strong>: 代理后链接中不保留原始 Host <ul><li>例如：<code>https://portal.sclib.cn/interlibSSO/goto/91/+c9v-me-mfc-s-9bnl9bm/periodical/hjkxyj202501001</code></li><li>这种代理后的链接中未包含原始 Host（<code>d.wanfangdata.com.cn</code>）。</li></ul></li><li><strong>类型 2</strong>: 代理后链接中保留了编码后的原始 Host <ul><li>例如：<code>http://d-wanfangdata-com-cn-s.ivpn.hit.edu.cn:1080/periodical/hjkxyj202501001</code></li><li>对于这一种代理，原始链接的 Host 被编码后嵌入到代理链接的域名中。（<code>d.wanfangdata.com.cn</code> 被编码为 <code>d-wanfangdata-com-cn</code>添加到了代理后的链接中）。</li></ul></li></ul></li><li><p><strong>创建代理规则</strong></p><ul><li>在 Zotero Connector 浏览器扩展中，进入「Proxies」→「Configured Proxies」</li><li>点击 <code>+</code> 按钮添加新规则</li></ul></li><li><p><strong>填写代理规则参数</strong></p><ul><li><strong>Login URL Schema</strong>: 填写登录 WebVPN 的登录入口链接。非必填项。</li><li><strong>Proxied URL Schema</strong>: 填写代理链接的结构。比较 WebVPN 代理链接和原始链接的结构，将代理链接中与原始链接相同的部分使用以下替换符来表示： <ul><li><code>%h</code>: 用于替换原始链接的 Host 部分（Host 中的 <code>.</code> 会被替换为 <code>-</code>）</li><li><code>%p</code>: 用于替换原始链接的 Path 部分</li><li><code>%u</code>: 用于替换完整的原始 URL</li></ul></li><li><strong>Hostnames</strong>: 点击 <code>+</code> 按钮，然后在「Hostname」中输入此规则适用的网站域名（如 <code>d.wanfangdata.com.cn</code>）</li></ul></li><li><p><strong>适配更多网站</strong></p><ul><li>如果不同网站的 Proxied URL Schema 相同，则该代理规则可用于多个网站，可直接在「Hostnames」中添加更多域名；</li><li>如果不同网站代理链接中未被替换的部分存在不同，需配置的 Proxied URL Schema 也就不同，则需在「Configured Proxies」创建多条规则。</li></ul></li></ol><p><img src="/assets/zotero-connector-proxies-hit.LAJwrOQH.png" alt="Zotero Connector Proxies 哈工大" width="1080" height="1039"></p><h4 id="常见-webvpn-代理的参数示例" tabindex="-1">常见 WebVPN 代理的参数示例 <a class="header-anchor" href="#常见-webvpn-代理的参数示例" aria-label="Permalink to “常见 WebVPN 代理的参数示例”">​</a></h4><p>下面，我们为两种常见的 WebVPN 代理类型给出相应的配置示例。</p><details class="details custom-block"><summary>WebVPN 代理类型 1：代理链接不保留原始 Host</summary><p>在这种类型下，代理后的链接完全使用新的域名。</p><p><strong>示例链接</strong></p><ul><li>原始链接：<code>https://d.wanfangdata.com.cn/periodical/hjkxyj202501001</code></li><li>代理后链接：<code>https://portal.sclib.cn/interlibSSO/goto/91/+c9v-me-mfc-s-9bnl9bm/periodical/hjkxyj202501001</code></li></ul><p><strong>配置参数确定方法</strong></p><ol><li>拆分原始链接</li></ol><table tabindex="0"><thead><tr><th>结构项</th><th>内容</th></tr></thead><tbody><tr><td>Protocol</td><td><code>https://</code></td></tr><tr><td>Host</td><td><code>d.wanfangdata.com.cn</code></td></tr><tr><td>Path</td><td><code>periodical/hjkxyj202501001</code></td></tr></tbody></table><ol start="2"><li><p>比较原始链接和代理后链接的结构，确定需要替换的部分</p><ul><li>原始链接中的 Host 部分未在代理后链接中出现，因此 <code>%h</code> 不需要使用；</li><li>原始链接中的 Path 部分 <code>periodical/hjkxyj202501001</code> 在代理后链接中保持不变，这部分内容可以用 <code>%p</code> 表示；</li><li>代理后链接中没有用到完整的原始 URL，因此 <code>%u</code> 不需要使用。</li></ul></li><li><p>应用替换符构建 Proxied URL Schema</p><p>将代理链接中可替换的部分替换为对应的替换符，其余部分直接保留原有内容，拼接 Proxied URL Schema。</p><ul><li>拆分代理后链接中可替换的部分：<code>https://portal.sclib.cn/interlibSSO/goto/91/+c9v-me-mfc-s-9bnl9bm/</code> + <code>periodical/hjkxyj202501001</code></li><li>使用替换符号替换可替换的部分：<code>https://portal.sclib.cn/interlibSSO/goto/91/+c9v-me-mfc-s-9bnl9bm/</code> + <code>%p</code></li></ul></li><li><p>配置参数</p></li></ol><ul><li>Login URL Schema（自行查询登录页面链接，非必填）: <code>https://portal.sclib.cn/interlibSSO/main/index.jsp</code></li><li>Proxied URL Schema: <code>https://portal.sclib.cn/interlibSSO/goto/91/+c9v-me-mfc-s-9bnl9bm/%p</code></li><li>Hostnames: 点击 <code>+</code> 按钮，在「Hostname」中输入 <code>d.wanfangdata.com.cn</code>，表示此规则仅对万方数据生效。</li></ul><ol start="5"><li>为其他网站添加更多的代理规则</li></ol><p>比较不同网站代理后链接，可以发现这一类的代理后链接中未被替换的部分存在不同，因此不能通过直接添加 <code>Hostnames</code> 兼容更多网站。如果需要为其他网站添加代理规则，需要重新分析其他原始链接和 WebVPN 代理后的链接之间的对应关系，配置更多代理规则。具体步骤与上述相同。</p><p><img src="/assets/zotero-connector-proxies-sclib.yCCU1q_z.png" alt="Zotero Connector Proxies 四川图书馆" width="1080" height="1051"></p></details><details class="details custom-block"><summary>WebVPN 代理类型 2：代理链接保留原始 Host</summary><p>在这种类型下，原始链接的 Host 被编码后嵌入到代理链接的域名中。</p><p><strong>示例链接</strong></p><ul><li>原始链接：<code>https://d.wanfangdata.com.cn/periodical/hjkxyj202501001</code></li><li>代理后链接：<code>http://d-wanfangdata-com-cn-s.ivpn.hit.edu.cn:1080/periodical/hjkxyj202501001</code></li></ul><p><strong>配置参数确定方法</strong></p><ol><li>拆分原始链接</li></ol><table tabindex="0"><thead><tr><th>结构项</th><th>内容</th></tr></thead><tbody><tr><td>Protocol</td><td><code>https://</code></td></tr><tr><td>Host</td><td><code>d.wanfangdata.com.cn</code></td></tr><tr><td>Path</td><td><code>periodical/hjkxyj202501001</code></td></tr></tbody></table><ol start="2"><li><p>比较原始链接和代理后链接的结构，确定需要替换的部分</p><ul><li>原始链接中的 Host 部分 <code>d.wanfangdata.com.cn</code> 在被编码后变为 <code>d-wanfangdata-com-cn</code>（Zotero Connector 会自动将 <code>.</code> 替换为 <code>-</code>），代理后链接中的相应内容可以用 <code>%h</code> 表示；</li><li>原始链接中的 Path 部分 <code>periodical/hjkxyj202501001</code> 在代理后链接中保持不变，这部分内容可以用 <code>%p</code> 表示；</li><li>代理后链接中没有用到完整的原始 URL，因此 <code>%u</code> 不需要使用。</li><li>代理后链接中编码后的 Host 之后有一个 <code>-s</code> 的部分（<code>d-wanfangdata-com-cn-s</code>），这部分说明原始链接的协议是 <code>https</code>，如果原始链接的协议是 <code>http</code>，则没有这一部分。这一部分无法用替换符表示，需要在 Proxied URL Schema 中直接保留。</li><li>无论原始链接的 Protocol 是 <code>http</code> 还是 <code>https</code>，代理后链接的协议都是 <code>http</code>，因此在 Proxied URL Schema 中需要将协议部分写为 <code>http://</code>。</li></ul></li><li><p>应用替换符构建 Proxied URL Schema</p><p>将代理链接中可替换的部分替换为对应的替换符，其余部分直接保留原有内容，拼接 Proxied URL Schema。</p><ul><li>拆分代理后链接中可替换的部分：<code>http://</code> + <code>d-wanfangdata-com-cn</code> + <code>-s</code> + <code>.ivpn.hit.edu.cn:1080/</code> + <code>periodical/hjkxyj202501001</code></li><li>使用替换符号替换可替换的部分：<code>http://</code> + <code>%h</code> + <code>-s</code> + <code>.ivpn.hit.edu.cn:1080/</code> + <code>%p</code></li></ul></li><li><p>配置参数</p></li></ol><ul><li>Login URL Schema（自行查询登录页面链接，非必填）: <code>https://ivpn.hit.edu.cn</code></li><li>Proxied URL Schema: <code>http://%h-s.ivpn.hit.edu.cn:1080/%p</code></li><li>Hostnames: 点击 <code>+</code> 按钮，在「Hostname」中输入 <code>d.wanfangdata.com.cn</code>，表示此规则对万方数据生效。</li></ul><ol start="5"><li>为其他网站添加更多的代理规则</li></ol><p>这种模式的 WebVPN 可以为多个不同的网站仅使用一条代理规则。因为无论访问哪个站点，代理链接的结构都是相同的，未被替换符替换的部分保持不变。仅有 Protocol 为 <code>http</code> 时需要另外添加一条去掉 <code>-s</code> 的规则（目前绝大多数网站已经使用 <code>https</code> 协议）。如果需要为其他网站添加代理规则，只需在「Hostnames」中添加更多的域名即可。</p><p>例如，如果您还需要访问 IEEE Xplore，则可以直接在 Hostnames 中添加 <code>ieeexplore.ieee.org</code>，表示此规则也适用于 IEEE Xplore。</p><p><img src="/assets/zotero-connector-proxies-hit.LAJwrOQH.png" alt="Zotero Connector Proxies 哈工大" width="1080" height="1039"></p></details><div class="tip custom-block"><p class="custom-block-title">提醒</p><p>不同学校/机构的 WebVPN 的链接结构可能不同，也可能出现其他情况，这里只是罗列了两种国内常见的 WebVPN 样式。您需要分析不同网站的 WebVPN 代理链接和原始链接之间的对应关系，根据配置步骤配置相应的代理规则。</p></div></details>`,4),a(`h2`,b,[c[19]||=s(`使用其它方式添加条目`,-1),i(w,{text:`初级`}),c[20]||=s(),c[21]||=a(`a`,{class:`header-anchor`,href:`#使用其它方式添加条目`,"aria-label":`Permalink to “使用其它方式添加条目”`},`​`,-1)]),c[31]||=a(`p`,null,`如果校外访问的方式无法抓取文献的元数据，或者在使用校外访问时无法抓取到 PDF 附件，您可以使用其他方式获取条目和附件。`,-1),c[32]||=a(`ul`,null,[a(`li`,null,[s(`通过附件添加条目。您可以通过校外访问服务手动下载 PDF 附件，然后`),a(`a`,{href:`./../add-items#通过附件添加条目-推荐`},`通过附件检索文献元数据`),s(`。通过附件检索元数据时无需使用校外访问服务，也无需拥有 PDF 附件的下载权限。`)]),a(`li`,null,[s(`分开获取条目和 PDF 附件。Zotero Connector 在抓取文献元数据时无需拥有 PDF 附件的下载权限。换言之，即便不适用校外访问，也可以通过 Zotero Connector 直接在数据库官网抓取文献的元数据。抓取完成后，再单独通过校外访问下载 PDF 附件，并将其`),a(`a`,{href:`./../add-attachments#为条目添加附件`},`添加到抓取到的条目中`),s(`。添加条目的可用方法详见`),a(`a`,{href:`./../add-items`},`添加条目教程`),s(`。`)])],-1),i(T),i(E)])}var S=n(l,[[`render`,x]]);export{c as __pageData,S as default};